			configSource = fmt.Sprintf("active profile (%s)", activeProfile.ID)
			providerFromProfile = true
			resolveDisplays()
			logDebug("Using active profile: %s / %s (profile: %s)", currentProvider, currentModel, activeProfile.ID)
